import json
NS='NiagaraToolsets.NiagaraToolset_System.'
def ref(sys, em):
    return {'system': {'refPath': sys}, 'emitterName': em, 'scriptName': '', 'moduleName': '', 'rendererIndex': -1, 'inputNameStack': []}
def compact(v):
    s = v.get('struct', {}).get('refPath', '')
    val = v.get('value')
    if 'Unsupported' in s: return None
    if 'Enum' in s: return val.get('displayName')
    if 'Dynamic' in s or 'Linked' in s or 'Data' in s: return s.split('_')[-1] + ':' + json.dumps(val)[:120]
    return json.dumps(val)[:100]
def dump(sys, em):
    r = execute_tool(NS+'GetEmitterInputValues', json.dumps({'emitterRef': ref(sys, em)}))['returnValue']
    out = {}
    for k, mods in r.items():
        if not isinstance(mods, list): continue
        for m in mods:
            d = {}
            for i in m.get('inputs', []):
                c = compact(i['value'])
                if c is not None: d[i['name']] = c
            out[k + '/' + m['moduleName']] = d
    return out
def run():
    return {'rain': dump('/Game/FX/NS_JamRain.NS_JamRain', 'Embers')}

