import json
NS = 'NiagaraToolsets.NiagaraToolset_System.'
SKIP = ('DeltaTime', 'Mass', 'Position', 'Velocity', 'PreviousVelocity', 'Force', 'Mesh Orientation', 'Rotational Velocity', 'Rotational Force', 'Rotational Inertia', 'Debug')
def ref(sys, em):
    return {'system': {'refPath': sys}, 'emitterName': em, 'scriptName': '', 'moduleName': '', 'rendererIndex': -1, 'inputNameStack': []}
def compact(v):
    s = v.get('struct', {}).get('refPath', '')
    val = v.get('value')
    if 'Unsupported' in s: return None
    if 'Enum' in s: return val.get('displayName')
    if 'StackInputData' in s: return s.split('_')[-1] + ':' + json.dumps(val)[:140]
    return json.dumps(val)[:100]
def dump(sys, em):
    r = execute_tool(NS + 'GetEmitterInputValues', json.dumps({'emitterRef': ref(sys, em)}))['returnValue']
    out = []
    for m in r:
        d = {}
        for i in m.get('inputs', []):
            if i['name'] in SKIP: continue
            c = compact(i['value'])
            if c is not None: d[i['name']] = c
        out.append([m.get('scriptName', ''), m.get('moduleName'), d])
    return out
def run():
    return {'x': dump(SYS, EM)}

