import json
NS = 'NiagaraToolsets.NiagaraToolset_System.'
def T(n, a): return execute_tool(n, json.dumps(a))
def ref(em, script='', module='', inputs=None, ri=-1):
    return {'system': {'refPath': S}, 'emitterName': em, 'scriptName': script, 'moduleName': module, 'rendererIndex': ri, 'inputNameStack': inputs or []}
def setv(em, script, module, inp, struct, value):
    return T(NS + 'SetStackInputData', {'stackInputRef': ref(em, script, module, [inp]), 'inputData': {'struct': {'refPath': struct}, 'value': value}})
def f(em, sc, mo, inp, x): return setv(em, sc, mo, inp, '/Script/Niagara.NiagaraFloat', {'value': x})
def b(em, sc, mo, inp, x): return setv(em, sc, mo, inp, '/Script/Niagara.NiagaraBool', {'value': -1 if x else 0})
def v3(em, sc, mo, inp, x, y, z): return setv(em, sc, mo, inp, '/Script/CoreUObject.Vector3f', {'x': x, 'y': y, 'z': z})
def v2(em, sc, mo, inp, x, y): return setv(em, sc, mo, inp, '/Script/CoreUObject.Vector2f', {'x': x, 'y': y})
def col(em, sc, mo, inp, r, g, bb, a): return setv(em, sc, mo, inp, '/Script/CoreUObject.LinearColor', {'r': r, 'g': g, 'b': bb, 'a': a})
def hlsl(em, sc, mo, inp, e): return setv(em, sc, mo, inp, '/Script/NiagaraEditor.NiagaraExt_StackInputData_HlslExpression', {'hlslExpression': e})
def enum(em, sc, mo, inp, display):
    cur = T(NS + 'GetStackInputData', {'stackInputRef': ref(em, sc, mo, [inp])})['returnValue']
    epath = cur['value']['enum']['refPath']
    info = json.loads(T('NiagaraToolsets.NiagaraToolset_Info.UEnum_Info', {'enum': {'refPath': epath}})['returnValue'])
    for v in info['Values']:
        if v['DisplayName'] == display:
            short = epath.split('.')[-1]
            nm = v['Name'] if '::' in v['Name'] else short + '::' + v['Name']
